WITH dim_totals AS (SELECT dim.status AS order_status, e.status AS payment_status, COUNT(*) AS rows_total, MAX(e.amount) AS max_amount FROM payments e INNER JOIN orders dim ON e.order_id = dim.id GROUP BY CUBE (dim.status, e.status)) SELECT order_status, payment_status, max_amount, CASE WHEN order_status RLIKE '^(CANCELLED|PENDING)$' THEN 'EXTENDED' WHEN order_status RLIKE '^(COMPLETED|SHIPPED)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS order_status_zone FROM dim_totals ORDER BY order_status_zone NULLS FIRST;
